package safety_test

import (
	"testing"

	qt "github.com/frankban/quicktest"
	"github.com/go-extras/go-kit/must"

	"ptah.run/core/ast"
	"ptah.run/core/platform"
	"ptah.run/engine/builtin"
	"ptah.run/migration/safety"
)

// An identity added to a column is judged by what an insert does after it, by
// the node and by the words it renders alike: one generated always refuses an
// insert that names the column, and one generated by default accepts every
// insert the column accepted before.
func TestAssessRendered_AddIdentity(t *testing.T) {
	tests := []struct {
		name         string
		generation   string
		wantSeverity safety.Severity
		wantReason   string
	}{
		{name: "ALWAYS", generation: "ALWAYS", wantSeverity: safety.Warning, wantReason: generatedAlwaysReason},
		{name: "BY DEFAULT", generation: "BY DEFAULT", wantSeverity: safety.Safe, wantReason: safeReason},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			c := qt.New(t)
			node := &ast.AlterTableNode{Name: "users", Operations: []ast.AlterOperation{&ast.AlterColumnOperation{
				ColumnName: "id", Action: ast.AlterColumnAddIdentity, IdentityGeneration: test.generation,
			}}}

			assessments, err := safety.AssessRendered(c.Context(), must.Must(builtin.New()), []ast.Node{node}, platform.Postgres)

			c.Assert(err, qt.IsNil)
			c.Assert(assessments, qt.HasLen, 1)
			c.Assert(assessments[0].Severity, qt.Equals, test.wantSeverity)
			c.Assert(assessments[0].Reason, qt.Equals, test.wantReason)
			words := assessText(c, platform.Postgres, assessments[0].Statement)
			c.Assert(words.Severity, qt.Equals, test.wantSeverity)
			c.Assert(words.Reason, qt.Equals, test.wantReason)
			c.Assert(safety.Classify(node), qt.Equals, test.wantSeverity)
		})
	}
}
